import{_ as e,o as l,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"CDS Reef: Orchestrator","description":"","frontmatter":{"title":"CDS Reef: Orchestrator","date":"2022-04-13T00:00:00.000Z","updated":"2022-04-13T00:00:00.000Z","tags":["Ceph","Orchestrator","分布式存储","自动化","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/CDS_Reef_-_Orchestrator.md","filePath":"posts/2022/CDS_Reef_-_Orchestrator.md","lastUpdated":1780459816000}'),i={name:"posts/2022/CDS_Reef_-_Orchestrator.md"};function o(s,a,n,h,d,u){return l(),r("div",null,[...a[0]||(a[0]=[t('<h2 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h2><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>本次会议重点讨论了Ceph Orchestrator的规划和改进，包括团队提出的初始议题和后续行动计划。会议涵盖了多个关键议题，如代理稳定化、服务循环透明度、升级历史记录、二进制文件重构、工作流程简化以及断开环境的支持等。</p><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><h4 id="代理稳定化" tabindex="-1">代理稳定化 <a class="header-anchor" href="#代理稳定化" aria-label="Permalink to &quot;代理稳定化&quot;">​</a></h4><ul><li><strong>现状</strong>：代理（agent）是一个非容器化的守护进程，运行在每个主机上，用于加速指标收集。</li><li><strong>问题</strong>：存在主机离线时的稳定性问题，需要进一步的稳定化和功能增强。</li><li><strong>计划</strong>：增强代理的稳定性，实现守护进程的部署和信息收集功能，使其能够异步执行，提高效率。</li></ul><h4 id="服务循环透明度" tabindex="-1">服务循环透明度 <a class="header-anchor" href="#服务循环透明度" aria-label="Permalink to &quot;服务循环透明度&quot;">​</a></h4><ul><li><strong>现状</strong>：当前服务事件和日志信息难以访问，不易于调试。</li><li><strong>计划</strong>：改进日志和事件的可访问性，提供CLI命令来查看历史操作和当前状态，增强调试功能。</li></ul><h4 id="升级历史记录" tabindex="-1">升级历史记录 <a class="header-anchor" href="#升级历史记录" aria-label="Permalink to &quot;升级历史记录&quot;">​</a></h4><ul><li><strong>现状</strong>：升级过程中的状态信息在完成后消失，难以追踪。</li><li><strong>计划</strong>：实现升级历史记录功能，记录升级的时间、版本等信息，便于后续查询和故障排查。</li></ul><h4 id="二进制文件重构" tabindex="-1">二进制文件重构 <a class="header-anchor" href="#二进制文件重构" aria-label="Permalink to &quot;二进制文件重构&quot;">​</a></h4><ul><li><strong>现状</strong>：当前二进制文件庞大且难以维护。</li><li><strong>计划</strong>：进行二进制文件的重构，将其模块化，便于未来的维护和开发。</li></ul><h4 id="工作流程简化" tabindex="-1">工作流程简化 <a class="header-anchor" href="#工作流程简化" aria-label="Permalink to &quot;工作流程简化&quot;">​</a></h4><ul><li><strong>计划</strong>：自动化一些复杂的工作流程，如监控堆栈镜像的设置和多站点部署，提高用户体验。</li></ul><h4 id="断开环境支持" tabindex="-1">断开环境支持 <a class="header-anchor" href="#断开环境支持" aria-label="Permalink to &quot;断开环境支持&quot;">​</a></h4><ul><li><strong>现状</strong>：当前对断开环境的文档和支持有限。</li><li><strong>计划</strong>：增强对断开环境的支持，确保在这些环境中的部署和运行更加顺畅。</li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>增强代理的稳定性和功能。</li><li>改进服务循环的透明度和调试功能。</li><li>实现升级历史记录功能。</li><li>进行二进制文件的重构。</li><li>自动化复杂的工作流程。</li><li>增强对断开环境的支持。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>继续推进代理的稳定化和功能增强。</li><li>开发和测试服务循环透明度的改进措施。</li><li>实现和测试升级历史记录功能。</li><li>完成二进制文件的重构工作。</li><li>自动化监控堆栈镜像设置和多站点部署流程。</li><li>增强断开环境的文档和支持。</li></ul><h3 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h3><ul><li>讨论了性能和规模的问题，计划在未来进行更多的测试和优化。</li><li>提及了资源感知调度的问题，计划在未来进行研究和开发。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><p>会议在讨论了所有议题后结束，感谢所有参与者的贡献，并期待未来的进展。</p>',24)])])}const g=e(i,[["render",o]]);export{_ as __pageData,g as default};
